#include <Servo.h>
#define Servopin 3
#define Sensorpin 2

Servo gateServo;

void setup() {
  Serial.begin(9600);
  gateServo.attach(Servopin);
  pinMode(Sensorpin, INPUT);
  gateServo.write(160);
}

void loop() {
  bool value = digitalRead(Sensorpin);
  Serial.println(value);

  if (value == 0) {
    gateServo.write(90);
    delay(5);
    gateServo.write(160);
    delay(5);
  } else {
    gateServo.write(160);
  }
}
